function executive_intelligence_metric_value(array$definition):float{$metric=(string)$definition['metric_key'];$companyId=!empty($definition['company_id'])?(int)$definition['company_id']:null;$context=executive_intelligence_process_context($definition);if($metric==='process_completion_pct'){$n=count($context['instances']);return$n?round(count(array_filter($context['instances'],static fn(array$row):bool=>$row['status']==='completed'))/$n*100,1):0.0;}if($metric==='process_sla_compliance_pct'){$rows=$context['step_instances'];$n=count($rows);$good=count(array_filter($rows,static function(array$row):bool{if(empty($row['due_at']))return true;if(($row['status']??'')==='completed')return!empty($row['completed_at'])&&strtotime((string)$row['completed_at'])<=strtotime((string)$row['due_at']);return strtotime((string)$row['due_at'])>=time();}));return$n?round($good/$n*100,1):100.0;}if($metric==='process_open_exceptions')return(float)count(array_filter($context['exceptions'],static fn(array$row):bool=>$row['status']!=='resolved'));if($metric==='process_overdue_steps')return(float)count(array_filter($context['step_instances'],static fn(array$row):bool=>in_array($row['status'],['active','pending'],true)&&!empty($row['due_at'])&&strtotime((string)$row['due_at'])<time()));if($metric==='process_average_cycle_hours'){$values=array_filter(array_map('intval',array_column(array_filter($context['instances'],static fn(array$row):bool=>$row['status']==='completed'),'cycle_seconds')));return$values?round(array_sum($values)/count($values)/3600,1):0.0;}$items=work_management_items();if(!empty($definition['entity_id']))$items=array_values(array_filter($items,static fn(array$row):bool=>(int)$row['entity_id']===(int)$definition['entity_id']));if($metric==='work_sla_compliance_pct'){$active=array_values(array_filter($items,static fn(array$row):bool=>!in_array($row['status'],['cancelled'],true)));$n=count($active);$good=count(array_filter($active,static fn(array$row):bool=>$row['status']==='completed'?!empty($row['completed_at'])&&strtotime((string)$row['completed_at'])<=strtotime((string)$row['due_at']):!work_management_item_overdue($row)));return$n?round($good/$n*100,1):100.0;}if($metric==='critical_open_work')return(float)count(array_filter($items,static fn(array$row):bool=>$row['priority']==='critical'&&!in_array($row['status'],['completed','cancelled'],true)));if($metric==='over_capacity_count'){$capacity=operational_calendar_capacity_snapshot();if($companyId)$capacity=array_values(array_filter($capacity,static fn(array$row):bool=>(int)$row['profile']['company_id']===$companyId));return(float)count(array_filter($capacity,static fn(array$row):bool=>$row['state']==='critical'));}if($metric==='savings_pipeline_usd'){$rows=executive_intelligence_filter_company(data_collection('savings_opportunities'),$companyId);return(float)array_sum(array_map(static fn(array$row):float=>in_array((string)($row['status']??''),['rejected','closed'],true)?0.0:(float)($row['expected_annual_savings']??0),$rows));}if($metric==='high_risk_suppliers'){$suppliers=data_collection('suppliers');if($companyId){$allowed=[];foreach(data_collection('supplier_companies')as$link)if((int)$link['company_id']===$companyId)$allowed[(int)$link['supplier_id']]=true;$suppliers=array_values(array_filter($suppliers,static fn(array$row):bool=>isset($allowed[(int)$row['id']])));}return(float)count(array_filter($suppliers,static fn(array$row):bool=>in_array((string)($row['risk_rating']??''),['high','critical'],true)));}if($metric==='past_due_purchase_orders'){$rows=executive_intelligence_filter_company(data_collection('purchase_orders'),$companyId);return(float)count(array_filter($rows,static fn(array$row):bool=>in_array((string)($row['status']??''),['past_due','partially_received'],true)));}if($metric==='open_ap_exceptions'){$rows=data_collection('procurement_invoice_exceptions');if($companyId){$invoices=[];foreach(data_collection('supplier_invoices')as$invoice)$invoices[(int)$invoice['id']]=$invoice