function executive_intelligence_evaluate(float$value,array$version):string{$target=(float)$version['target_value'];$warning=(float)$version['warning_value'];if(($version['direction']??'higher_better')==='higher_better')return$value>=$target?'on_target':($value>=$warning?'warning':'critical');return$value<=$target?'on_target':($value<=$warning?'warning':'critical');}
