function executive_intelligence_generate_snapshot(int$definitionId,?string$periodStart=null,?string$periodEnd=null):array{require_permission('executive_intelligence.snapshot');$definition=executive_intelligence_find_definition($definitionId);if(!$definition)throw new RuntimeException('KPI definition not found.');$version=executive_intelligence_active_version($definition);if(!$version)throw new RuntimeException('The KPI needs a published active version before snapshot generation.');$periodStart??=date('Y-m-01');$periodEnd??=date('Y-m-d');$key=executive_intelligence_snapshot_key($definitionId,(int)$version['id'],$periodEnd);foreach(executive_intelligence_kpi_snapshots($definitionId)as$existing)if(hash_equals((string)$existing['snapshot_key'],$key))return$existing;$actual=executive_intelligence_metric_value($definition);$prior=executive_intelligence_kpi_snapshots($definitionId);$previous=$prior[0]??null;$trend='flat';$forecast=$actual;$confidence=45;if($previous){$delta=$actual-(float)$previous['actual_value'];$trend=$delta>0.001?'up':($delta<-0.001?'down':'flat');$forecast=round($actual+$delta,2);$confidence=65;}if(count($prior)>=2)$confidence=80;$context=executive_intelligence_process_context($definition);return executive_intelligence_save_snapshot(['id'=>null,'definition_id'=>$definitionId,'version_id'=>$version['id'],'entity_id'=>$definition['entity_id'],'company_id'=>$definition['company_id'],'period_start'=>$periodStart,'period_end'=>$periodEnd,'actual_value'=>$actual,'target_value'=>$version['target_value'],'status'=>executive_intelligence_evaluate($actual,$version),'trend_direction'=>$trend,'forecast_value'=>$forecast,'confidence_pct'=>$confidence,'evidence_json'=>json_encode(['metric_key'=>$definition['metric_key'],'process_id'=>$definition['process_id'],'process_step_id'=>$definition['process_step_id'],'process_instances'=>count($context['instances']),'step_instances'=>count($context['step_instances']),'exceptions'=>count($context['exceptions']),'generated_fr