function executive_intelligence_agent_extend_workspace(array$workspace):array{$metrics=executive_intelligence_metrics();$risk=[];foreach(executive_intelligence_goals()as$goal){$state=executive_intelligence_goal_state($goal);if(in_array($state,['warning','critical'],true))$risk[]=['goal'=>$goal,'state'=>$state,'actual'=>executive_intelligence_goal_actual($goal)];}usort($risk,static fn(array$a,array$b):int=>($a['state']==='critical'?0:1)<=>($b['state']==='critical'?0:1));$rows=[];foreach(array_slice($risk,0,6)as$row)$rows[]='<li><strong>'.executive_intelligence_agent_escape($row['goal']['goal_name']).'</strong> · '.executive_intelligence_agent_escape(status_label($row['state'])).' · actual '.executive_intelligence_agent_escape($row['actual']??'not measured').' / target '.executive_intelligence_agent_escape($row['goal']['target_value']).' · owner '.executive_intelligence_agent_escape(data_user_name((int)$row['goal']['owner_user_id'])).'</li>';if(!$rows)$rows[]='<li>No measured goals are currently below their governed target.</li>';$prompt=['icon'=>'◎','title'=>'Executive command center','description'=>'Explain goals, KPI performance, process bottlenecks, forecasts, scorecards, and executive decisions.','prompt'=>'Which goals and KPIs require executive attention, why, and what governed action should happen next?','keywords'=>['executive command','goal','kpi','scorecard','performance','forecast','objective','business review'],'response_title'=>'Executive Performance Agent','response_html'=>'<p><strong>'.$metrics['goals'].' goals · '.$metrics['at_risk_goals'].' at risk · '.$metrics['critical_kpis'].' critical KPIs · '.$metrics['open_decisions'].' open decisions.</strong></p><ul>'.implode('',$rows).'</ul><p>Process maps, canonical records, Section 26 work, and Section 27 calendar evidence remain authoritative. Recommendations require human review.</p><a class="agent-inline-link" href="'.executive_intelligence_agent_escape(app_url('executive-command.php')).'">Open Executive Command Center →</a>','evidence'=>[$metrics['at_risk_goals'].' at-risk goals',$metrics['critical_kpis'].' critical KPIs',$metrics['process']['open_exceptions'].' open process exceptions',$metrics['work']['overdue'].' overdue work'],'actions'=>[['type'=>'link','icon'=>'◎','label'=>'Open executive command','description'=>'Review governed performance evidence','href'=>app_url('executive-command.php')],['type'=>'prompt','icon'=>'!','label'=>'Explain KPI risk','description'=>'Trace performance to process and work evidence','prompt'=>'Trace each critical KPI to its process map, exceptions, work items, owners, and next executive decision.']],'confidence'=>'High','generated_at'=>date('Y-m-d H:i:s'),'human_review'=>'Required before goals, KPI definitions, scorecards, or decisions change','missing_data'=>[]];array_unshift($workspace['prompts'],$prompt);$workspace['metrics']['executive_goals']=$metrics['goals'];$workspace['metrics']['at_risk_goals']=$metrics['at_risk_goals'];$workspace['metrics']['critical_kpis']=$metrics['critical_kpis'];$workspace['metrics']['published_scorecards']=$metrics['published_scorecards'];if(isset($workspace['briefing']['priorities']))foreach(array_slice($risk,0,3)as$row)$workspace['briefing']['priorities'][]=['severity'=>$row['state']==='critical'?'critical':'high','category'=>'Executive performance','title'=>$row['goal']['goal_name'],'description'=>'Actual '.($row['actual']??'not measured').' versus target '.$row['goal']['target_value'].'.','meta'=>data_user_name((int)$row['goal']['owner_user_id']).' · '.status_label($row['state']),'href'=>app_url('executive-command.php?tab=goals'),'action_label'=>'Open goal','agent_prompt'=>'Explain the process, KPI evidence, owner, forecast, and next governed action for '.$row['goal']['goal_number'].'.'];return$workspace;}
function executive_intelligence_render_styles():void{echo '<style>.exec-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin:18px 0}.exec-metrics article,.exec-card{background:#fff;border:1px solid #dfe4ea;border-radius:16px;padding:16px;box-shadow:0 8px 28px rgba(17,24,39,.05)}.exec-metrics span,.exec-eyebrow{display:block;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#6b7280}.exec-metrics strong{display:block;font-size:28px;margin:5px 0}.exec-tabs{display:flex;gap:8px;overflow:auto;margin:0 0 18px}.exec-tabs a{padding:10px 14px;border-radius:999px;border:1px solid #dfe4ea;background:#fff;white-space:nowrap}.exec-tabs a.active{background:#111827;color:#fff}.exec-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:18px}.exec-list{display:grid;gap:12px}.exec-row{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(3,minmax(90px,.5fr));gap:12px;align-items:center;padding:14px;border:1px solid #e5e7eb;border-radius:14px}.exec-row p,.exec-row small{margin:3px 0;color:#6b7280}.exec-row.critical{border-left:5px solid #b91c1c}.exec-row.warning{border-left:5px solid #d97706}.exec-row.on_target{border-left:5px solid #15803d}.exec-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.exec-form label{display:grid;gap:6px;font-weight:700}.exec-form input,.exec-form select,.exec-form textarea{width:100%;padding:10px 12px;border:1px solid #cfd6df;border-radius:10px;background:#fff}.exec-span-2{grid-column:span 2}.exec-score{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.exec-score div{padding:12px;border-radius:12px;background:#f5f7fa}.exec-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:980px){.exec-metrics{grid-template-columns:repeat(2,1fr)}.exec-grid{grid-template-columns:1fr}.exec-row{grid-template-columns:1fr 1fr}.exec-form{grid-template-columns:1fr}.exec-span-2{grid-column:auto}}</style>';}

